violating:
import { Effect } from "effect"

export interface ShippingQuote {
  readonly service: "standard" | "express"
  readonly feeCents: number
  readonly deliveryDays: number
}

export const quoteShipping = (
  weightGrams: number,
  express: boolean
): ShippingQuote => ({
  service: express ? "express" : "standard",
  feeCents: 450 + Math.ceil(weightGrams / 500) * 125 + (express ? 900 : 0),
  deliveryDays: express ? 1 : 5
})

export const shippingQuoteTool = {
  name: "shipping_quote",
  description: "Estimate shipping cost and delivery time for a parcel.",
  execute: Effect.fn("ShippingQuoteTool.execute")(function* (input: {
    readonly weightGrams: number
    readonly express?: boolean
  }) {
    if (!Number.isFinite(input.weightGrams) || input.weightGrams <= 0) {
      return yield* Effect.fail(new Error("Parcel weight must be positive"))
    }

    const quote: ShippingQuote = quoteShipping(
      input.weightGrams,
      input.express ?? false
    )

    return {
      content: [
        {
          type: "text" as const,
          text: JSON.stringify({
            service: quote.service,
            price: (quote.feeCents / 100).toFixed(2),
            currency: "USD",
            estimatedDeliveryDays: quote.deliveryDays
          })
        }
      ]
    }
  })
}

